import{_ as a,o as t,c as e,a2 as s}from"./chunks/framework.BXzK3EA4.js";const o="/assets/rak%E5%AE%98%E7%BD%91%E7%99%BB%E5%BD%95%E9%A1%B5%E9%9D%A2.CSLHdMw1.png",l="/assets/%E6%9F%A5%E7%9C%8B%E4%BC%98%E6%83%A0%E6%9D%83%E7%9B%8A.BOq6CPrV.png",i="/assets/%E6%9F%A5%E7%9C%8B%E6%88%91%E7%9A%84%E6%9D%83%E7%9B%8A.Cy-n3j0k.png",n="/assets/%E8%B4%AD%E4%B9%B0%E4%B8%AD%E5%BF%83.DmS76l1s.png",p="/assets/%E6%9F%90%E4%B8%AA%E4%BA%A7%E5%93%81%E9%85%8D%E7%BD%AE1.Coy9q0Fr.png",g="/assets/%E9%80%89%E6%8B%A9%E4%BC%98%E6%83%A0%E5%88%B8.D2DCfvTw.png",m="/assets/order%20summary.CE89GlFz.png",c="/assets/%E8%B4%A6%E5%8D%95.BExOGg6D.png",u="/assets/%E5%B7%B2%E4%BB%98%E6%AC%BE%E8%B4%A6%E5%8D%95.BamIdUhM.png",h="/assets/%E8%BF%94%E5%9B%9E%E6%9C%8D%E5%8A%A1%E5%88%97%E8%A1%A8.kc3HAYL-.png",A=JSON.parse('{"title":"购买 RakSmart 产品","description":"","frontmatter":{"title":"购买 RakSmart 产品"},"headers":[],"relativePath":"beginners-guide/buy-products/purchase.md","filePath":"beginners-guide/buy-products/purchase.md","lastUpdated":1794229843000}'),d={name:"beginners-guide/buy-products/purchase.md"};function E(k,r,b,_,B,f){return t(),e("div",null,[...r[0]||(r[0]=[s('<p>您可以分别通过官网产品入口和控制台购买中心入口购买 RakSmart 产品，不同的购买入口支持的产品配置方法和付款流程相同。</p><hr><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ol><li><p>注册 RakSmart 账号，详细步骤可参考<a href="/beginners-guide/register-account/">注册 RakSmart 账号</a>。如果您已开通账号，请忽略此步骤。</p></li><li><p>为账户充值，确保账户有足够的资金，以免购买产品失败。具体操作，请参考<a href="/beginners-guide/wallet/balance.html#为-raksmart-账号充值">为 RakSmart 账号充值</a>。</p><blockquote><p><strong>说明</strong></p><p>目前仅 VPS 支持小时计费。小时计费会从账户余额中扣款，为了保证业务连续性，请保持余额充足。</p></blockquote></li><li><p>了解 RakSmart 产品三种不同的购买方式：<a href="/beginners-guide/buy-products/purchase-methods.html">了解 RakSmart 产品购买方式</a>。</p></li></ol><hr><h3 id="步骤一-登录-raksmart-官网" tabindex="-1">步骤一：登录 RakSmart 官网 <a class="header-anchor" href="#步骤一-登录-raksmart-官网" aria-label="Permalink to &quot;步骤一：登录 RakSmart 官网&quot;">​</a></h3><p>登录 <a href="https://cn.raksmart.com/" target="_blank" rel="noreferrer">RakSmart 官网</a>。您可根据 RakSmart 官网<strong>产品介绍</strong>，了解各产品的功能特性，以及适用的业务场景。</p><p><img src="'+o+'" alt="rak官网登录页面.png"></p><hr><h3 id="步骤二-领取优惠权益" tabindex="-1">步骤二：领取优惠权益 <a class="header-anchor" href="#步骤二-领取优惠权益" aria-label="Permalink to &quot;步骤二：领取优惠权益&quot;">​</a></h3><p>在购买产品前，您可以先了解 RakSmart 推出的优惠活动，以更优惠的方式购买产品。</p><ol><li><p>查看优惠权益。</p><p>在顶部导航单击<strong>最新活动</strong>，打开活动下拉列表页面。您可以通过优惠活动和福利专区选择需要购买的产品或服务。RakSmart 官网为新用户提供了各种满减优惠券、优惠活动和优惠产品，个人开发者、企业可享受不同的优惠权益。</p><p><img src="'+l+'" alt="查看优惠权益.png"></p></li><li><p>领取优惠权益。</p><p>成功领取权益后，您可前往<a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">控制台</a>-&gt;<strong>我的钱包</strong>查看已领取的权益。 <img src="'+i+'" alt="查看我的权益.png"></p></li></ol><hr><h3 id="步骤三-购买-raksmart-产品" tabindex="-1">步骤三：购买 RakSmart 产品 <a class="header-anchor" href="#步骤三-购买-raksmart-产品" aria-label="Permalink to &quot;步骤三：购买 RakSmart 产品&quot;">​</a></h3><ol><li><p>选择<a href="/beginners-guide/buy-products/purchase-methods.html#官网优惠活动入口">官网优惠活动入口</a>、<a href="/beginners-guide/buy-products/purchase-methods.html#官网推荐产品入口">官网推荐产品入口</a>或<a href="/beginners-guide/buy-products/purchase-methods.html#控制台购买中心入口">控制台购买中心入口</a>其中一种购买入口，进入<strong>产品列表</strong>或<strong>购买中心</strong>页面。</p></li><li><p>在<strong>购买中心</strong>页面，选择所需产品，单击<strong>立即订购</strong>，进入<strong>产品配置</strong>页面（价格计算器）。 <img src="'+n+'" alt="购买中心"></p></li><li><p>按需完成产品配置。关于配置信息的详细介绍请参考各产品的购买配置说明。 <img src="'+p+'" alt="某个产品配置"></p><blockquote><p>说明</p><ul><li>不同的计费模式（小时计费、月付、季度付、半年付、年付）会在成本效益和资源使用弹性上有所差异，购买产品之前，建议先确定好适合您业务的产品计费模式。更长的付费周期能享受更高的折扣价格。</li><li>目前仅 VPS 支持小时计费。小时计费会从账户余额中扣款，为了保证业务连续性，请保持余额充足。</li></ul></blockquote></li><li><p>可选择使用优惠券（若有）。 <img src="'+g+'" alt="选择优惠券"></p><blockquote><p>说明</p><ul><li>选好配置后系统会自动选中最佳优惠，您也可以手动取消/切换。切换优惠后可点击<strong>获取最新价格</strong>来查看优惠后的金额，确认无误后再点击确认使用。</li><li>若优惠券上方有<strong>影响续费</strong>标签，表示该优惠可能在后续续费时继续生效，具体以页面展示和优惠规则为准。</li><li>若想要应用的优惠券被<strong>其他账单占用</strong>，可单击优惠券下方的<strong>链接</strong>进入所在账单将优惠券取消应用后，再返回当前页面刷新重试。</li></ul></blockquote></li><li><p>计算总价。</p><p>如选择的是包年包月模式，购买页面会展示优惠金额、订单总金额；如选择的是按小时付费模式，则只显示每小时单价。 <img src="'+m+'" alt="order summary"></p></li><li><p>填写<strong>订单备注</strong>（选填）、勾选同意<strong>服务条款</strong>（必选）并单击<strong>立即购买</strong>生成账单。</p></li><li><p>进入账单页面后，请核对产品信息、优惠券、代金券、优惠金额和应付金额。确认无误后，再选择付款方式并完成付款。支持使用余额付款，若需要充值请参考<a href="/beginners-guide/wallet/balance.html#为-raksmart-账号充值">为 RakSmart 账号充值</a>。 <img src="'+c+'" alt="账单"></p><blockquote><p>说明</p><ul><li>账单付清前，您可以在账单页面<strong>继续调整</strong>优惠券或代金券；账单付清后，优惠券和代金券仅支持查看，不可再修改。</li><li>一张优惠券或代金券，只能应用在一个未支付账单中。如需<strong>切换</strong>到其他账单使用，请先在原账单中取消应用。具体可用状态以页面展示为准。</li></ul></blockquote></li><li><p>（可选）付款完成之后，可点击账单中<strong>返回服务列表</strong>按钮，快速查看您已购买/开通的产品。 <img src="'+u+'" alt="已付款账单"></p><blockquote><p>说明</p><ul><li>点击返回服务列表默认筛选展示与当前账单有关联的产品，点击切换状态即可筛选对应状态的所有产品。 <img src="'+h+'" alt="返回服务列表"></li></ul></blockquote></li><li><p>查看邮件。</p><p>购买产品成功后，您将会收到订单信息确认、账单支付确认和产品信息的邮件通知。请注意查收和保存产品相关信息，如物理服务器远程连接用户名和密码。</p></li></ol><hr><h3 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h3><p>购买 RakSmart 各产品可参考：</p><ul><li><a href="/dedicatedserver/product-intro/overview.html">购买物理服务器</a>；</li><li><a href="/baremetal/product-intro/overview.html">购买裸机云服务器</a>；</li><li><a href="/vps/product-intro/overview.html">购买 VPS</a>。</li></ul><hr><h3 id="后续操作" tabindex="-1">后续操作 <a class="header-anchor" href="#后续操作" aria-label="Permalink to &quot;后续操作&quot;">​</a></h3><p>完成 RakSmart 产品购买后，您可以开始使用 RakSmart 产品了。</p><ul><li><p><strong>查看账单费用</strong></p><p>查看账单明细，参考<a href="/beginners-guide/billing/billing-management.html">账单管理</a>。</p></li><li><p><strong>资源调整</strong></p><p>调整资源配比，参考<a href="/beginners-guide/manage-products/upgrade-downgrade.html">升降级</a>。</p></li></ul>',23)])])}const q=a(d,[["render",E]]);export{A as __pageData,q as default};
